class NowTests(TestCase):
    def test_sql_precision(self):
        compiler = Article.objects.all().query.get_compiler(connection=connection)
        for vendor, expected_sql in (
            ("mysql", "CURRENT_TIMESTAMP(6)"),
            ("sqlite", "STRFTIME('%%Y-%%m-%%d %%H:%%M:%%f', 'NOW')"),
        ):
            with self.subTest(vendor=vendor):
                with mock.patch.object(connection, "vendor", vendor):
                    sql, params = compiler.compile(Now())
                self.assertEqual(sql, expected_sql)
                self.assertEqual(params, [])

    @skipUnless(connection.vendor in {"mysql", "sqlite"}, "MySQL and SQLite precision")
    def test_fractional_seconds(self):
        article = Article.objects.create(
            title="How to Time Travel",
            text=lorem_ipsum,
            written=timezone.now(),
        )
        for attempt in range(3):
            Article.objects.filter(pk=article.pk).update(published=Now())
            article.refresh_from_db()
            if article.published.microsecond:
                break
            # A query can execute exactly at a whole-second boundary.
            time.sleep(0.01)
        self.assertNotEqual(article.published.microsecond, 0)
        if connection.vendor == "sqlite":
            self.assertEqual(article.published.microsecond % 1000, 0)

    def test_basic(self):

    def as_mysql(self, compiler, connection, **extra_context):
        return self.as_sql(
            compiler, connection, template="CURRENT_TIMESTAMP(6)", **extra_context
        )

    def as_sqlite(self, compiler, connection, **extra_context):
        return self.as_sql(
            compiler,
            connection,
            template="STRFTIME('%%%%Y-%%%%m-%%%%d %%%%H:%%%%M:%%%%f', 'NOW')",
            **extra_context,
        )


